const { createClient } = require('redis');
const { v4: uuidv4 } = require('uuid');

class KumvaSessionManager {
    constructor(RED) {
        this.RED = RED;
        this.client = createClient({
            url: process.env.REDIS_URL || 'redis://localhost:6379'
        });

        this.client.on('error', err => console.error('Redis Client Error', err));
        this.client.connect().then(() => console.log('Kumva Redis connected'));
    }

    async createSession(phoneNumber, flowId, campaignId) {
        const sessionId = `kumva:${uuidv4()}`;
        const session = {
            sessionId,
            phoneNumber,
            flowId,
            campaignId,
            currentNodeId: null,
            state: {},
            status: 'active',
            createdAt: Date.now(),
            updatedAt: Date.now()
        };

        await this.client.set(`session:${sessionId}`, JSON.stringify(session), { EX: 3600 * 6 }); // 6h TTL
        return session;
    }

    async getSession(sessionId) {
        const data = await this.client.get(`session:${sessionId}`);
        return data ? JSON.parse(data) : null;
    }

    async updateSession(sessionId, updates) {
        const session = await this.getSession(sessionId);
        if (!session) return null;

        Object.assign(session, updates, { updatedAt: Date.now() });
        await this.client.set(`session:${sessionId}`, JSON.stringify(session), { EX: 3600 * 6 });
        return session;
    }

    async setWaitingNode(sessionId, nodeId, waitingData) {
        await this.updateSession(sessionId, {
            currentNodeId: nodeId,
            waitingData
        });
    }

    async markCompleted(sessionId) {
        await this.updateSession(sessionId, { status: 'completed' });
    }

    async getActiveSessions() {
        // For monitoring (Redis scan in production)
        return [];
    }

    async saveResponse(sessionId, questionId, answer) {
        const key = `response:${sessionId}:${questionId}`;
        await this.client.set(key, JSON.stringify({
            answer,
            timestamp: Date.now()
        }));
        // Also persist to main session
        await this.updateSession(sessionId, {
            [`answers.${questionId}`]: answer
        });
    }

    async saveResponse(sessionId, questionId, answer) {
        const key = `resp:${sessionId}:${questionId}`;
        await this.client.set(key, JSON.stringify({ answer, ts: Date.now() }), { EX: 86400 });

        const session = await this.getSession(sessionId);
        if (session) {
            session.answers = session.answers || {};
            session.answers[questionId] = answer;
            await this.updateSession(sessionId, session);
        }
    }

    async markCompleted(sessionId) {
        await this.updateSession(sessionId, { status: 'completed', endedAt: Date.now() });
    }
}

let instance;
module.exports = {
    getInstance: (RED) => {
        if (!instance) instance = new KumvaSessionManager(RED);
        return instance;
    }
};